import { formOptions, useForm, useStore } from "@tanstack/react-form";

interface RegisterForm {
  firstName: string;
  lastName: string;
  age: number | undefined;
  email: string;
  password: string;
  confirmPassword: string;
  address: {
    street: string;
    city: string;
    state: string;
    zipCode: string;
  };
  skills: Array<{
    name: string;
    id: string;
    level: "beginner" | "intermediate" | "expert";
  }>;
  acceptTerms: boolean;
}

const defaultValues: RegisterForm = {
  firstName: "",
  lastName: "",
  age: undefined,
  email: "",
  password: "",
  confirmPassword: "",
  address: { street: "", city: "", state: "", zipCode: "" },
  skills: [
    {
      name: "HTML",
      id: crypto.randomUUID(),
      level: "beginner",
    },
    {
      name: "CSS",
      id: crypto.randomUUID(),
      level: "beginner",
    },
    {
      name: "JavaScript",
      id: crypto.randomUUID(),
      level: "beginner",
    },
  ],
  acceptTerms: false,
};

const formOpts = formOptions({
  defaultValues,
});

export default function RegisterForm() {
  const form = useForm({
    ...formOpts,
    onSubmit: ({ value }) => {
      console.log(value);
    },
    listeners: {
      onChange: ({ formApi, fieldApi }) => {
        console.log(formApi, fieldApi);
      },
    },
  });
  const values = useStore(form.store, (state) => state.values);

  return (
    <div className="text-start max-w-[400px] p-4">
      <form
        onSubmit={(e) => {
          e.preventDefault();
          form.handleSubmit();
        }}
      >
        <form.Field
          name="firstName"
          listeners={{
            onChange: ({ value }) => {
              if (!value) {
                form.setFieldValue("lastName", "");
              }
            },
          }}
        >
          {(field) => {
            return (
              <div className="mb-4">
                {/* <pre>{JSON.stringify(field.state.meta, null, 2)}</pre> */}
                <input
                  type="text"
                  placeholder="First Name"
                  className="bg-black text-white border border-white p-2 w-full"
                  value={field.state.value}
                  onChange={(e) => field.handleChange(e.target.value)}
                  onBlur={field.handleBlur}
                />
              </div>
            );
          }}
        </form.Field>
        <form.Subscribe selector={(state) => state.values.firstName}>
          {(firstName) => (
            <>
              {firstName && (
                <form.Field name="lastName">
                  {(field) => (
                    <div className="mb-4">
                      <input
                        className="bg-black text-white border border-white p-2 w-full"
                        placeholder="Last Name"
                        value={field.state.value}
                        onBlur={field.handleBlur}
                        onChange={(e) => field.handleChange(e.target.value)}
                      />
                    </div>
                  )}
                </form.Field>
              )}
            </>
          )}
        </form.Subscribe>
        <form.Field name="address.street">
          {(field) => (
            <div className="mb-4">
              <input
                className="bg-black text-white border border-white p-2 w-full"
                placeholder="Street"
                value={field.state.value}
                onBlur={field.handleBlur}
                onChange={(e) => field.handleChange(e.target.value)}
              />
            </div>
          )}
        </form.Field>
        <form.Field name="skills" mode="array">
          {(field) => {
            return (
              <div>
                Skills
                <div>
                  {field.state.value.map((skill, index) => (
                    <div
                      key={skill.id}
                      className="flex items-center mb-2 gap-2"
                    >
                      <span>{skill.name}</span>
                      <form.Field name={`skills[${index}].level`}>
                        {(subField) => (
                          <select
                            className="bg-black text-white border border-white p-2 w-full"
                            value={subField.state.value}
                            onBlur={subField.handleBlur}
                            onChange={(e) => {
                              subField.handleChange(e.target.value as any);
                            }}
                          >
                            <option value="beginner">Beginner</option>
                            <option value="intermediate">Intermediate</option>
                            <option value="expert">Expert</option>
                          </select>
                        )}
                      </form.Field>
                      <button
                        className="bg-red-700 text-white p-1 ms-2"
                        onClick={() => field.removeValue(index)}
                      >
                        X
                      </button>
                    </div>
                  ))}
                </div>
                <button
                  className="bg-yellow-700 text-black p-2"
                  onClick={() => {
                    field.pushValue({
                      name: `New Skill ${field.state.value.length + 1}`,
                      id: crypto.randomUUID(),
                      level: "beginner",
                    });
                  }}
                >
                  Add Skill
                </button>
              </div>
            );
          }}
        </form.Field>
        <form.Field name="acceptTerms">
          {(field) => {
            return (
              <div className="mb-4 mt-4">
                <label className="flex items-center gap-2">
                  <input
                    className="bg-black text-white border border-white p-2"
                    type="checkbox"
                    checked={field.state.value}
                    onBlur={field.handleBlur}
                    onChange={(e) => field.handleChange(e.target.checked)}
                  />
                  Accept Terms
                </label>
              </div>
            );
          }}
        </form.Field>
        <button className="bg-yellow-500 text-black p-2 mt-4" type="submit">
          Submit
        </button>
      </form>
      <pre className="mt-10">{JSON.stringify(values, null, 2)}</pre>
    </div>
  );
}

