};

const formOpts = formOptions({
  defaultValues,
});

export default function RegisterForm() {
  const form = useForm({
    ...formOpts,
    onSubmit: ({ value }) => {
      console.log(value);
    },
    validators: {
      onChange: ({ value }) => {
        return {
          fields: {
            firstName: !value.firstName ? "First name is required" : undefined,
            "address.street": !value.address.street
