                            .map((error) => error?.message)
                            .join(", ")}
                        </div>
                      )}
                    </div>
                  )}
                </form.Field>
              )}
            </>
          )}
        </form.Subscribe>
        <form.Field name="address.street">
          {(field) => (
            <div className="mb-4">
              <input
                className="bg-black text-white border border-white p-2 w-full"
                placeholder="Street"
                value={field.state.value}
                onBlur={field.handleBlur}
                onChange={(e) => field.handleChange(e.target.value)}
              />
              {!field.state.meta.isValid && (
                <div className="text-red-500 mt-2" role="alert">
                  {field.state.meta.errors
                    .map((error) => error?.message)
                    .join(", ")}
                </div>
              )}
            </div>
          )}
        </form.Field>
        <form.Field name="password">
          {(field) => (
            <div className="mb-4">
              <input
                className="bg-black text-white border border-white p-2 w-full"
                type="password"
                value={field.state.value}
                placeholder="Password"
                onBlur={field.handleBlur}
                onChange={(e) => field.handleChange(e.target.value)}
              />
              {!field.state.meta.isValid && (
                <div className="text-red-500 mt-2" role="alert">
                  {field.state.meta.errors
                    .map((error) => error?.message)
                    .join(", ")}
                </div>
              )}
            </div>
          )}
        </form.Field>

        <form.Field name="confirmPassword">
          {(field) => (
            <div className="mb-4">
              <input
                className="bg-black text-white border border-white p-2 w-full"
                type="password"
                value={field.state.value}
                placeholder="Confirm Password"
                onBlur={field.handleBlur}
                onChange={(e) => field.handleChange(e.target.value)}
              />
              {!field.state.meta.isValid && (
                <div className="text-red-500 mt-2" role="alert">
                  {field.state.meta.errors
                    .map((error) => error?.message)
                    .join(", ")}
                </div>
              )}
            </div>
          )}
        </form.Field>

        <form.Field name="skills" mode="array">
          {(field) => {
            return (
              <div>
                Skills
                <div>
                  {field.state.value.map((skill, index) => (
                    <div
                      key={skill.id}
                      className="flex items-center mb-2 gap-2"
                    >
                      <span>{skill.name}</span>
                      <form.Field name={`skills[${index}].level`}>
                        {(subField) => (
                          <>
                            <select
                              className="bg-black text-white border border-white p-2 w-full"
                              value={subField.state.value}
                              onBlur={subField.handleBlur}
                              onChange={(e) => {
                                subField.handleChange(e.target.value as any);
                              }}
                            >
                              <option value="beginner">Beginner</option>
                              <option value="intermediate">Intermediate</option>
                              <option value="expert">Expert</option>
                            </select>
                            {!field.state.meta.isValid && (
                              <div className="text-red-500 mt-2" role="alert">
                                {field.state.meta.errors
                                  .map((error) => error?.message)
                                  .join(", ")}
                              </div>
                            )}
                          </>
                        )}
                      </form.Field>
                      <button
                        className="bg-red-700 text-white p-1 ms-2"
                        onClick={() => field.removeValue(index)}
                      >
                        X
                      </button>
                    </div>
                  ))}
                </div>
                <button
                  className="bg-yellow-700 text-black p-2"
                  onClick={() => {
                    field.pushValue({
                      name: `New Skill ${field.state.value.length + 1}`,
                      id: crypto.randomUUID(),
                      level: "beginner",
                    });
                  }}
                >
                  Add Skill
                </button>
              </div>
            );
          }}
        </form.Field>
        <form.Field name="acceptTerms">
          {(field) => {
            return (
              <div className="mb-4 mt-4">
                <label className="flex items-center gap-2">
                  <input
                    className="bg-black text-white border border-white p-2"
                    type="checkbox"
                    checked={field.state.value}
                    onBlur={field.handleBlur}
                    onChange={(e) => field.handleChange(e.target.checked)}
                  />
                  Accept Terms
                </label>
                {!field.state.meta.isValid && (
                  <div className="text-red-500 mt-2" role="alert">
                    {field.state.meta.errors
                      .map((error) => error?.message)
                      .join(", ")}
                  </div>
                )}
              </div>
            );
          }}
        </form.Field>
        <form.Subscribe selector={(state) => state.canSubmit}>
          {(canSubmit) => (
            <div>
              <button
                disabled={!canSubmit}
                className="bg-yellow-500 text-black p-2 mt-4 disabled:opacity-40 disabled:cursor-not-allowed"
                type="submit"
                onClick={() => form.handleSubmit({ submitAction: "save" })}
              >
                Save
              </button>
              <button
                disabled={!canSubmit}
                className="bg-yellow-500 text-black p-2 mt-4 disabled:opacity-40 disabled:cursor-not-allowed"
                type="submit"
                onClick={() => form.handleSubmit({ submitAction: "goback" })}
              >
                Save & Go back
              </button>
            </div>
          )}
        </form.Subscribe>
      </form>
      <pre className="mt-10">{JSON.stringify(values, null, 2)}</pre>
    </div>
  );
}

