    skills: z.array(
      z.object({
        name: z.string(),
        id: z.string(),
        level: z.enum(["beginner", "intermediate", "expert"]),
      })
    ),
  })
  .refine((data) => data.password === data.confirmPassword, {
    error: "Passwords do not match",
    path: ["confirmPassword"],
  });
const defaultValues: z.infer<typeof formSchema> = {
  firstName: "",
  lastName: "",
  age: undefined,
  // email: "",
  password: "",
  confirmPassword: "",
  address: { street: "" },
  skills: [
    {
      name: "HTML",
      id: crypto.randomUUID(),
      level: "beginner",
    },
    {
      name: "CSS",
      id: crypto.randomUUID(),
      level: "beginner",
    },
    {
      name: "JavaScript",
      id: crypto.randomUUID(),
      level: "beginner",
    },
  ],
  acceptTerms: false,
};

const formOpts = formOptions({
  defaultValues,
});

export default function RegisterForm() {
  const form = useForm({
    ...formOpts,
    onSubmit: ({ value, meta }) => {
      console.log(value);
      console.log(formSchema.parse(value));
      console.log(meta);
    },
    validators: {
      onDynamic: formSchema,
    },
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "blur",
    }),
  });
  const values = useStore(form.store, (state) => state.values);
  const errors = useStore(form.store, (state) => state.errors);

  return (
    <div className="text-start max-w-[400px] p-4">
      {/* {JSON.stringify(errors)} */}
      <form
        onSubmit={(e) => {
          e.preventDefault();
          form.handleSubmit({ key: "value" });
        }}
      >
        <FieldGroup>
          <form.Field
            name="firstName"
            validators={{
              onChangeAsyncDebounceMs: 500,
              onChangeAsync: z.string().refine(
                async (value) => {
                  await new Promise((r) => setTimeout(r, 1000));
                  return value !== "John";
                },
                {
                  error: "First name cannot be John (async check).",
                }
              ),
            }}
            listeners={{
              onChange: ({ value }) => {
                if (!value) {
                  form.setFieldValue("lastName", "");
                }
              },
            }}
          >
            {(field) => {
              return (
                <Field>
                  <FieldLabel htmlFor="firstName">First Name</FieldLabel>
                  <Input
                    id="firstName"
                    type="text"
                    placeholder="John Doe"
                    value={field.state.value}
                    onBlur={field.handleBlur}
                    onChange={(e) => field.handleChange(e.target.value)}
                  />
                  <FieldDescription>Your First Name.</FieldDescription>
                  {!field.state.meta.isValid && (
                    <FieldError>
                      {field.state.meta.errors
                        .map((error) => error?.message)
                        .join(", ")}
                    </FieldError>
                  )}
                </Field>
              );
            }}
          </form.Field>
          <form.Subscribe selector={(state) => state.values.firstName}>
            {(firstName) => (
              <>
                {firstName && (
                  <form.Field name="lastName">
                    {(field) => (
                      <Field>
                        <FieldLabel htmlFor="lastName">Last Name</FieldLabel>
                        <Input
                          id="lastName"
                          type="text"
                          placeholder="Last Name"
                          value={field.state.value}
                          onBlur={field.handleBlur}
                          onChange={(e) => field.handleChange(e.target.value)}
                        />
                        <FieldDescription>Your last name.</FieldDescription>
                        {!field.state.meta.isValid && (
                          <FieldError>
                            {field.state.meta.errors
                              .map((error) => error?.message)
                              .join(", ")}
                          </FieldError>
                        )}
                      </Field>
                    )}
                  </form.Field>
                )}
              </>
            )}
          </form.Subscribe>
          <form.Field name="address.street">
            {(field) => (
              <Field>
                <FieldLabel htmlFor="address.street">Street</FieldLabel>
                <Input
                  id="address.street"
                  type="text"
                  placeholder="Street"
                  value={field.state.value}
                  onBlur={field.handleBlur}
                  onChange={(e) => field.handleChange(e.target.value)}
                />
                <FieldDescription>Your street address.</FieldDescription>
                {!field.state.meta.isValid && (
                  <FieldError>
                    {field.state.meta.errors
                      .map((error) => error?.message)
                      .join(", ")}
                  </FieldError>
                )}
              </Field>
            )}
          </form.Field>
          <form.Field name="password">
            {(field) => (
              <Field>
                <FieldLabel htmlFor="password">Password</FieldLabel>
                <Input
                  id="password"
                  type="password"
                  placeholder="Password"
                  value={field.state.value}
                  onBlur={field.handleBlur}
                  onChange={(e) => field.handleChange(e.target.value)}
                />
                <FieldDescription>
                  Your password (must be at least 8 characters long).
                </FieldDescription>
                {!field.state.meta.isValid && (
                  <FieldError>
                    {field.state.meta.errors
                      .map((error) => error?.message)
                      .join(", ")}
                  </FieldError>
                )}
              </Field>
            )}
          </form.Field>

          <form.Field name="confirmPassword">
            {(field) => (
              <Field>
                <FieldLabel htmlFor="confirmPassword">
                  Confirm Password
                </FieldLabel>
                <Input
                  id="confirmPassword"
                  type="password"
                  placeholder="Confirm Password"
                  value={field.state.value}
                  onBlur={field.handleBlur}
                  onChange={(e) => field.handleChange(e.target.value)}
                />
                <FieldDescription>Confirm your password.</FieldDescription>
                {!field.state.meta.isValid && (
                  <FieldError>
                    {field.state.meta.errors
                      .map((error) => error?.message)
                      .join(", ")}
                  </FieldError>
                )}
              </Field>
            )}
          </form.Field>

          <form.Field name="skills" mode="array">
            {(field) => {
              return (
                <FieldSet>
                  <FieldLegend>Skills</FieldLegend>
                  <FieldDescription>
                    Your skills and expertise.
                  </FieldDescription>
                  <FieldGroup>
                    {field.state.value.map((skill, index) => {
                      return (
                        <div key={skill.id}>
                          <form.Field
                            key={index}
                            name={`skills[${index}].level`}
                          >
                            {(subField) => {
                              return (
                                <Field>
                                  <div className="flex  gap-2 ">
                                    <FieldLabel>{skill.name}</FieldLabel>
                                    <Select
                                      value={subField.state.value}
                                      onValueChange={(value) =>
                                        subField.handleChange(value as any)
                                      }
                                    >
                                      <SelectTrigger
                                        onBlur={subField.handleBlur}
                                      >
                                        <SelectValue placeholder="Choose department" />
                                      </SelectTrigger>
                                      <SelectContent>
                                        <SelectItem value="beginner">
                                          Beginner
                                        </SelectItem>
                                        <SelectItem value="intermediate">
                                          Intermediate
                                        </SelectItem>
                                        <SelectItem value="expert">
                                          Expert
                                        </SelectItem>
                                      </SelectContent>
                                    </Select>

                                    <Button
                                      variant="destructive"
                                      type="button"
                                      onClick={() => field.removeValue(index)}
                                    >
                                      Remove
                                    </Button>
                                  </div>

                                  {!field.state.meta.isValid && (
                                    <FieldError>
                                      {field.state.meta.errors
                                        .map((error) => error?.message)
                                        .join(", ")}
                                    </FieldError>
                                  )}
                                </Field>
                              );
                            }}
                          </form.Field>
                        </div>
                      );
                    })}
                    <Button
                      onClick={() =>
                        field.pushValue({
                          name: `New Skill ${field.state.value.length + 1}`,
                          id: crypto.randomUUID(),
                          level: "beginner",
                        })
                      }
                      variant="secondary"
                      type="button"
                    >
                      Add Skill
                    </Button>
                  </FieldGroup>
                </FieldSet>
              );
            }}
          </form.Field>
          <form.Field name="acceptTerms">
            {(field) => {
              return (
                <Field>
                  <div className="flex items-center gap-2">
                    <Checkbox
                      checked={field.state.value}
                      onCheckedChange={(checked) =>
                        field.handleChange(checked === true)
                      }
                      onBlur={field.handleBlur}
                    />
                    <FieldContent>
                      <FieldLabel htmlFor="finder-pref-9k2-sync-folders-nep">
                        Accept Terms
                      </FieldLabel>
                    </FieldContent>
                  </div>
                  {!field.state.meta.isValid && (
                    <FieldError>
                      {field.state.meta.errors
                        .map((error) => error?.message)
                        .join(", ")}
                    </FieldError>
                  )}
                </Field>
              );
            }}
          </form.Field>
          <form.Subscribe selector={(state) => state.canSubmit}>
            {(canSubmit) => (
              <div>
                <Button
                  disabled={!canSubmit}
                  type="submit"
                  onClick={() => form.handleSubmit({ submitAction: "save" })}
                >
                  Save
                </Button>
                <Button
                  disabled={!canSubmit}
                  type="submit"
                  onClick={() => form.handleSubmit({ submitAction: "goback" })}
                >
                  Save & Go back
                </Button>
              </div>
            )}
          </form.Subscribe>
        </FieldGroup>
      </form>
      <pre className="mt-10">{JSON.stringify(values, null, 2)}</pre>
    </div>
  );
}

