import { createFormHook } from "@tanstack/react-form";
import { fieldContext, formContext } from "./form-context";
import TextInput from "@/components/form/TextInput";
import Select from "@/components/form/Select.tsx";
import Checkbox from "@/components/form/Checkbox.tsx";

export const { useAppForm, withForm, withFieldGroup } = createFormHook({
  fieldContext: fieldContext,
  formContext: formContext,
  fieldComponents: {
    TextInput: TextInput,
    Select: Select,
    Checkbox: Checkbox,
  },
  formComponents: {},
});

import { Button } from "@/components/ui/button";
import {
  FieldDescription,
  FieldGroup,
  FieldLegend,
  FieldSet,
} from "@/components/ui/field";
import { revalidateLogic } from "@tanstack/react-form";
import { registerFormOpts, registerFormSchema } from "./shared";
import { useAppForm } from "@/hooks/form";

export default function RegisterForm() {
  const form = useAppForm({
    ...registerFormOpts,
    onSubmit: ({ value, meta }) => {
      console.log(value);
      console.log(registerFormSchema.parse(value));
      console.log(meta);
    },
    validators: {
      onDynamic: registerFormSchema,
    },
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "blur",
    }),
  });

  return (
    <div className="text-start max-w-[400px] p-4">
      {/* {JSON.stringify(errors)} */}
      <form
        onSubmit={(e) => {
          e.preventDefault();
          form.handleSubmit({ key: "value" });
        }}
      >
        <FieldGroup>
          <form.AppField name="firstName">
            {(field) => {
              return (
                <field.TextInput
                  id="firstName"
                  label="First Name"
                  description="Your First Name"
                />
              );
            }}
          </form.AppField>

          <form.AppField name="lastName">
            {(field) => (
              <field.TextInput
                id="lastName"
                label="Last Name"
                description="Your Last Name"
              />
            )}
          </form.AppField>

          <form.AppField name="address.street">
            {(field) => {
              return (
                <field.TextInput
                  label="Street"
                  id="addressStreet"
                  description="Some Description"
                />
              );
            }}
          </form.AppField>
          <form.AppField name="password">
            {(field) => {
              return (
                <field.TextInput
                  label="Password"
                  id="password"
                  type="password"
                  description="Your password (must be at least 8 characters long)"
                />
              );
            }}
          </form.AppField>

          <form.AppField name="confirmPassword">
            {(field) => {
              return (
                <field.TextInput
                  label="Confirm Password"
                  id="confirmPassword"
                  type="password"
                  description="Confirm your password."
                />
              );
            }}
          </form.AppField>

          <form.AppField name="skills" mode="array">
            {(field) => {
              return (
                <FieldSet>
                  <FieldLegend>Skills</FieldLegend>
                  <FieldDescription>
                    Your skills and expertise.
                  </FieldDescription>
                  <FieldGroup>
                    {field.state.value.map((skill, index) => {
                      return (
                        <div key={skill.id} className="p-4 bg-gray-900 rounded">
                          <p className="mb-4 font-bold">{skill.name}</p>
                          <form.AppField
                            key={index}
                            name={`skills[${index}].level`}
                          >
                            {(subField) => {
                              return (
                                <subField.Select
                                  label="Skill Level"
                                  id={`skills-${index}-level`}
                                />
                              );
                            }}
                          </form.AppField>
                          <Button
                            className="mt-2"
                            variant="destructive"
                            type="button"
                            onClick={() => field.removeValue(index)}
                          >
                            Remove
                          </Button>
                        </div>
                      );
                    })}
                    <Button
                      onClick={() =>
                        field.pushValue({
                          name: `New Skill ${field.state.value.length + 1}`,
                          id: crypto.randomUUID(),
                          level: "beginner",
                        })
                      }
                      variant="secondary"
                      type="button"
                    >
                      Add Skill
                    </Button>
                  </FieldGroup>
                </FieldSet>
              );
            }}
          </form.AppField>
          <form.AppField name="acceptTerms">
            {(field) => {
              return <field.Checkbox id="acceptTerms" label="Accept Terms" />;
            }}
          </form.AppField>
          <form.Subscribe selector={(state) => state.canSubmit}>
            {(canSubmit) => (
              <div>
                <Button
                  disabled={!canSubmit}
                  type="submit"
                  onClick={() => form.handleSubmit({ submitAction: "save" })}
                >
                  Save
                </Button>
                <Button
                  disabled={!canSubmit}
                  type="submit"
                  onClick={() => form.handleSubmit({ submitAction: "goback" })}
                >
                  Save & Go back
                </Button>
              </div>
            )}
          </form.Subscribe>
        </FieldGroup>
      </form>
    </div>
  );
}

