              {(field) => {
                return (
                  <FieldSet>
                    <FieldLegend>Skills</FieldLegend>
                    <FieldDescription>
                      Your skills and expertise.
                    </FieldDescription>
                    <FieldGroup>
                      {field.state.value.map((skill, index) => {
                        return (
                          <div
                            key={skill.id}
                            className="p-4 bg-gray-900 rounded"
                          >
                            <p className="mb-4 font-bold">{skill.name}</p>
                            <form.AppField
                              key={index}
                              name={`skills[${index}].level`}
                            >
                              {(subField) => {
                                return (
                                  <subField.Select
                                    label="Skill Level"
                                    id={`skills-${index}-level`}
                                  />
                                );
                              }}
                            </form.AppField>
                            <Button
                              className="mt-2"
                              variant="destructive"
                              type="button"
                              onClick={() => field.removeValue(index)}
                            >
                              Remove
                            </Button>
                          </div>
                        );
                      })}
                      <Button
                        onClick={() =>
                          field.pushValue({
                            name: `New Skill ${field.state.value.length + 1}`,
                            id: crypto.randomUUID(),
                            level: "beginner",
                          })
                        }
                        variant="secondary"
                        type="button"
                      >
                        Add Skill
                      </Button>
                    </FieldGroup>
                  </FieldSet>
                );
              }}
            </form.AppField>
            <form.AppField name="acceptTerms">
              {(field) => {
                return <field.Checkbox id="acceptTerms" label="Accept Terms" />;
              }}
            </form.AppField>
          </FieldGroup>

          <form.SubmitButton />
        </form>
      </form.AppForm>
    </div>
  );
}

