import { Button } from "@/components/ui/button";
import {
  FieldDescription,
  FieldGroup,
  FieldLegend,
  FieldSet,
} from "@/components/ui/field";
import { revalidateLogic } from "@tanstack/react-form";
import { registerFormOpts, registerFormSchema } from "./shared";
import { useAppForm } from "@/hooks/form";

export default function RegisterForm() {
  const form = useAppForm({
    ...registerFormOpts,
    onSubmit: ({ value, meta }) => {
      console.log(value);
      console.log(registerFormSchema.parse(value));
      console.log(meta);
    },
    validators: {
      onDynamic: registerFormSchema,
    },
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "blur",
    }),
  });

  return (
    <div className="text-start max-w-[400px] p-4">
      {/* {JSON.stringify(errors)} */}
      <form.AppForm>
        <form
          onSubmit={(e) => {
            e.preventDefault();
            form.handleSubmit({ key: "value" });
          }}
        >
          <FieldGroup>
            <form.AppField name="firstName">
              {(field) => {
                return (
                  <field.TextInput
                    id="firstName"
                    label="First Name"
                    description="Your First Name"
                  />
                );
              }}
            </form.AppField>

            <form.AppField name="lastName">
              {(field) => (
                <field.TextInput
                  id="lastName"
                  label="Last Name"
                  description="Your Last Name"
                />
              )}
            </form.AppField>

            <form.AppField name="address.street">
              {(field) => {
                return (
                  <field.TextInput
                    label="Street"
                    id="addressStreet"
                    description="Some Description"
                  />
                );
              }}
            </form.AppField>
            <form.AppField name="password">
              {(field) => {
                return (
                  <field.TextInput
                    label="Password"
                    id="password"
                    type="password"
                    description="Your password (must be at least 8 characters long)"
                  />
                );
              }}
            </form.AppField>

            <form.AppField name="confirmPassword">
              {(field) => {
                return (
                  <field.TextInput
                    label="Confirm Password"
                    id="confirmPassword"
                    type="password"
                    description="Confirm your password."
                  />
                );
              }}
            </form.AppField>

            <form.AppField name="skills" mode="array">
              {(field) => {
                return (
                  <FieldSet>
                    <FieldLegend>Skills</FieldLegend>
                    <FieldDescription>
                      Your skills and expertise.
                    </FieldDescription>
                    <FieldGroup>
                      {field.state.value.map((skill, index) => {
                        return (
                          <div
                            key={skill.id}
                            className="p-4 bg-gray-900 rounded"
                          >
                            <p className="mb-4 font-bold">{skill.name}</p>
                            <form.AppField
                              key={index}
                              name={`skills[${index}].level`}
                            >
                              {(subField) => {
                                return (
                                  <subField.Select
                                    label="Skill Level"
                                    id={`skills-${index}-level`}
                                  />
                                );
                              }}
                            </form.AppField>
                            <Button
                              className="mt-2"
                              variant="destructive"
                              type="button"
                              onClick={() => field.removeValue(index)}
                            >
                              Remove
                            </Button>
                          </div>
                        );
                      })}
                      <Button
                        onClick={() =>
                          field.pushValue({
                            name: `New Skill ${field.state.value.length + 1}`,
                            id: crypto.randomUUID(),
                            level: "beginner",
                          })
                        }
                        variant="secondary"
                        type="button"
                      >
                        Add Skill
                      </Button>
                    </FieldGroup>
                  </FieldSet>
                );
              }}
            </form.AppField>
            <form.AppField name="acceptTerms">
              {(field) => {
                return <field.Checkbox id="acceptTerms" label="Accept Terms" />;
              }}
            </form.AppField>
          </FieldGroup>

          <form.SubmitButton />
        </form>
      </form.AppForm>
    </div>
  );
}

import { formOptions } from "@tanstack/react-form";
import * as z from "zod";

export const registerFormSchema = z
  .object({
    firstName: z
      .string()
      .min(2, "First name should be at least 2 characters.")
      .max(50),
    lastName: z
      .string()
      .min(2, "Last name should be at least 2 characters.")
      .max(50),
    age: z
      .number()
      .min(18, "You must be at least 18 years old.")
      .max(120, "Age must be less than 120.")
      .optional(),
    acceptTerms: z.boolean().refine((val) => val === true, {
      message: "You must accept the terms and conditions.",
    }),
    email: z.email("Invalid email address.").optional(),
    password: z.string().min(6, "Password should be at least 6 characters."),
    confirmPassword: z.string(),
    address: z.object({
      street: z.string().min(5, "Street should be at least 5 characters."),
      city: z
        .string()
        .min(2, "City should be at least 2 characters.")
        .optional(),
      state: z
        .string()
        .min(2, "State should be at least 2 characters.")
        .optional(),
      zipCode: z
        .string()
        .min(5, "Zip Code should be at least 5 characters.")
        .optional(),
    }),
    skills: z.array(
      z.object({
        name: z.string(),
        id: z.string(),
        level: z.enum(["beginner", "intermediate", "expert"]),
      })
    ),
  })
  .refine((data) => data.password === data.confirmPassword, {
    error: "Passwords do not match",
    path: ["confirmPassword"],
  });
export const defaultValues: z.infer<typeof registerFormSchema> = {
  firstName: "",
  lastName: "",
  age: undefined,
  // email: "",
  password: "",
  confirmPassword: "",
  address: { street: "" },
  skills: [
    {
      name: "HTML",
      id: crypto.randomUUID(),
      level: "beginner",
    },
    {
      name: "CSS",
      id: crypto.randomUUID(),
      level: "beginner",
    },
    {
      name: "JavaScript",
      id: crypto.randomUUID(),
      level: "beginner",
    },
  ],
  acceptTerms: false,
};

export const registerFormOpts = formOptions({
  defaultValues,
});

