import { Suspense } from "react";
import RegisterForm from "./lib/register-form/RegisterForm";

function App() {
  return (
    <>
      <Suspense fallback={<p>Loading...</p>}>
        <RegisterForm />
      </Suspense>
    </>
  );
}

export default App;

import { useFieldContext } from "@/hooks/form-context";
import { Field, FieldContent, FieldError, FieldLabel } from "../ui/field";

import { Checkbox } from "../ui/checkbox";

export default function CustomCheckbox({
  label,
  id,
}: {
  label: string;
  id: string;
}) {
  const field = useFieldContext<boolean>();
  return (
    <Field>
      <div className="flex items-center gap-2">
        <Checkbox
          id={id}
          checked={field.state.value}
          onCheckedChange={(checked) => field.handleChange(checked === true)}
          onBlur={field.handleBlur}
        />
        <FieldContent>
          <FieldLabel htmlFor={id}>{label}</FieldLabel>
        </FieldContent>
      </div>
      {!field.state.meta.isValid && (
        <FieldError>
          {field.state.meta.errors.map((error) => error?.message).join(", ")}
        </FieldError>
      )}
    </Field>
  );
}

import { withFieldGroup } from "@/hooks/form";
import * as z from "zod";

export const passwordsSchema = z
  .object({
    password: z.string().min(6, "Password should be at least 6 characters."),
    confirmPassword: z.string(),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "Passwords do not match",
    path: ["confirmPassword"], // Optional: specifies where the error should appear
  });

const defaultValues: z.infer<typeof passwordsSchema> = {
  password: "",
  confirmPassword: "",
};

export const PasswordFields = withFieldGroup({
  defaultValues,
  render: function Render({ group }) {
    return (
      <>
        <group.AppField name="password">
          {(field) => {
            return (
              <field.TextInput
                label="Password"
                id="password"
                type="password"
                description="Your password (must be at least 8 characters long)"
              />
            );
          }}
        </group.AppField>

        <group.AppField name="confirmPassword">
          {(field) => {
            return (
              <field.TextInput
                label="Confirm Password"
                id="confirmPassword"
                type="password"
                description="Confirm your password."
              />
            );
          }}
        </group.AppField>
      </>
    );
  },
});

import { useFieldContext } from "@/hooks/form-context";
import { Field, FieldDescription, FieldError, FieldLabel } from "../ui/field";
import {
